package io.coolbox.ensemble;
import io.coolbox.internal.*;import com.sun.jna.ptr.DoubleByReference;
/** Bagged regression forest (Python: {@code tree_ensemble.RandomForestRegressor}). */
public final class RandomForestRegressor extends NativeHandle {private static final EnsembleNative N=EnsembleNative.INSTANCE;private int features;public RandomForestRegressor(int trees,int depth){this(trees,depth,5489);}public RandomForestRegressor(int trees,int depth,int seed){super(N.coolbox_trees_random_forest_regressor_new(trees,depth,seed),N::coolbox_trees_random_forest_regressor_free);}public RandomForestRegressor fit(double[][] x,double[] y){features=Matrices.columns(x);if(y.length!=x.length)throw new IllegalArgumentException("target count differs from rows");ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_trees_random_forest_regressor_fit(handle(),Matrices.flatten(x),x.length,features,y,e.pointer(),e.capacity()));return this;}public double predict(double[] sample){DoubleByReference o=new DoubleByReference();ErrorBuffer e=new ErrorBuffer();e.check(N.coolbox_trees_random_forest_regressor_predict(handle(),sample,sample.length,o,e.pointer(),e.capacity()));return o.getValue();}}
